import { randomUUID } from 'node:crypto'
import type { H3Event } from 'h3'
import { READ_ONLY_ERROR, type Note, type NoteFlash, type SharedNote } from '#shared/types/note'

const SESSION_COOKIE = 'sid'

const notesByUser = new Map<string, Note[]>([
  ['ada', [
    { id: 'n1', title: 'Buy milk', body: '', number: 2, pinned: false, archived: false, createdAt: '2026-01-15T09:00:00.000Z' },
    { id: 'n2', title: 'Call Bob', body: '', number: 1, pinned: false, archived: false, createdAt: '2026-01-14T09:00:00.000Z' },
  ]],
  ['bob', [{ id: 'n3', title: "Bob's secret", body: '', number: 1, pinned: false, archived: false, createdAt: '2026-01-10T09:00:00.000Z' }]],
])

let nextNoteId = 4

/** Highest note number each user has ever had; deleting notes does not lower it, so numbers are never reused. */
const lastNumberByUser = new Map<string, number>([['ada', 2], ['bob', 1]])

const sessions = new Map<string, string>()

/** The user's most recent delete, kept until it is undone, the notes change again or the user signs out. */
const lastDeletedByUser = new Map<string, { note: Note; index: number }>()

/** Any other change to a user's notes makes the last delete no longer undoable. */
function forgetDeleted(name: string): void {
  lastDeletedByUser.delete(userKey(name))
}

export function lastDeleted(name: string): Note | null {
  return lastDeletedByUser.get(userKey(name))?.note ?? null
}

/** Puts the last deleted note back at its old place, unchanged. */
export function undoDelete(name: string): Note | null {
  const key = userKey(name)
  const entry = lastDeletedByUser.get(key)
  if (!entry) return null
  lastDeletedByUser.delete(key)
  const notes = notesByUser.get(key) ?? []
  notes.splice(Math.min(entry.index, notes.length), 0, entry.note)
  notesByUser.set(key, notes)
  return entry.note
}

function userKey(name: string): string {
  return name.toLowerCase()
}

function userNotes(name: string): Note[] {
  return notesByUser.get(userKey(name)) ?? []
}

/** Notes that are not archived: pinned first; otherwise newest first, as stored. */
export function listNotes(name: string): Note[] {
  const notes = userNotes(name).filter((note) => !note.archived)
  return [...notes.filter((note) => note.pinned), ...notes.filter((note) => !note.pinned)]
}

/** Every note the user owns, archived ones included, in the list page's order: pinned first, then newest first, as stored. */
export function listOwnNotes(name: string): Note[] {
  const notes = userNotes(name)
  return [...notes.filter((note) => note.pinned), ...notes.filter((note) => !note.pinned)]
}

/** Archived notes, newest first, as stored. */
export function listArchivedNotes(name: string): Note[] {
  return userNotes(name).filter((note) => note.archived)
}

/** Archived notes count too: their titles stay taken. `exceptId` leaves one note out of the check, so a note never clashes with itself when renamed. */
export function noteExists(name: string, title: string, exceptId?: string): boolean {
  const normalized = title.trim().toLowerCase()
  return userNotes(name).some((note) => note.id !== exceptId && note.title.trim().toLowerCase() === normalized)
}

/** Adds per user within any `ADD_WINDOW_MS`; only notes actually added count. */
export const ADD_LIMIT = 10
const ADD_WINDOW_MS = 60_000
const addTimesByUser = new Map<string, number[]>()

function recentAdds(name: string, now = Date.now()): number[] {
  const key = userKey(name)
  const times = (addTimesByUser.get(key) ?? []).filter((time) => now - time < ADD_WINDOW_MS)
  addTimesByUser.set(key, times)
  return times
}

/** Seconds until the user may add another note; 0 when they may add one now. */
export function addRetryAfter(name: string): number {
  const now = Date.now()
  const times = recentAdds(name, now)
  if (times.length < ADD_LIMIT) return 0
  return Math.max(1, Math.ceil((times[times.length - ADD_LIMIT]! + ADD_WINDOW_MS - now) / 1000))
}

export function addNote(name: string, title: string): Note {
  const key = userKey(name)
  recentAdds(name).push(Date.now())
  const notes = notesByUser.get(key) ?? []
  const number = (lastNumberByUser.get(key) ?? 0) + 1
  lastNumberByUser.set(key, number)
  const note: Note = { id: `n${nextNoteId++}`, title, body: '', number, pinned: false, archived: false, createdAt: new Date().toISOString() }
  notes.unshift(note)
  notesByUser.set(key, notes)
  forgetDeleted(name)
  return note
}

export function deleteNote(name: string, id: string): boolean {
  const notes = notesByUser.get(userKey(name))
  const index = notes?.findIndex((note) => note.id === id) ?? -1
  if (!notes || index === -1) return false
  const [note] = notes.splice(index, 1)
  lastDeletedByUser.set(userKey(name), { note: note!, index })
  return true
}

/** Deletes the listed notes that are not archived. A bulk delete cannot be undone, so it also forgets the last delete. */
export function deleteNotes(name: string, ids: string[]): number {
  const key = userKey(name)
  const wanted = new Set(ids)
  const notes = notesByUser.get(key) ?? []
  const kept = notes.filter((note) => note.archived || !wanted.has(note.id))
  const removed = notes.length - kept.length
  if (removed === 0) return 0
  for (const note of notes) if (!kept.includes(note)) sharesByNote.delete(note.id)
  notesByUser.set(key, kept)
  forgetDeleted(name)
  return removed
}

/** Archives the listed notes that are not archived yet. */
export function archiveNotes(name: string, ids: string[]): number {
  const wanted = new Set(ids)
  const notes = userNotes(name).filter((note) => !note.archived && wanted.has(note.id))
  for (const note of notes) note.archived = true
  if (notes.length) forgetDeleted(name)
  return notes.length
}

export function findNote(name: string, id: string): Note | null {
  return userNotes(name).find((note) => note.id === id) ?? null
}

/** One of the user's own notes (archived included) by its number; never another user's note. */
export function findNoteByNumber(name: string, number: number): Note | null {
  return userNotes(name).find((note) => note.number === number) ?? null
}

/** Changes only the title; position, pin and creation date stay as they are. */
export function renameNote(name: string, id: string, title: string): Note | null {
  const note = findNote(name, id)
  if (!note) return null
  note.title = title
  forgetDeleted(name)
  return note
}

/** Changes title and body together; position, pin and creation date stay as they are. */
export function updateNote(name: string, id: string, title: string, body: string): Note | null {
  const note = findNote(name, id)
  if (!note) return null
  note.title = title
  note.body = body
  forgetDeleted(name)
  return note
}

/** Session id -> the outcome of the last save posted without JavaScript, for the page the post redirects to. */
const flashBySession = new Map<string, NoteFlash & { noteId: string }>()

export function setNoteFlash(event: H3Event, noteId: string, flash: NoteFlash): void {
  const id = getCookie(event, SESSION_COOKIE)
  if (id) flashBySession.set(id, { ...flash, noteId })
}

/** Shown once: any note page read clears it, and only that note's page gets it. */
export function takeNoteFlash(event: H3Event, noteId: string | undefined): NoteFlash | null {
  const id = getCookie(event, SESSION_COOKIE)
  const flash = id ? flashBySession.get(id) : undefined
  if (!flash) return null
  flashBySession.delete(id!)
  if (flash.noteId !== noteId) return null
  const { noteId: _, ...rest } = flash
  return rest
}

export function setPinned(name: string, id: string, pinned: boolean): Note | null {
  const note = userNotes(name).find((note) => note.id === id)
  if (!note) return null
  note.pinned = pinned
  forgetDeleted(name)
  return note
}

/** Only flips the flag, so a restored note keeps its title, pin, date and position. */
export function setArchived(name: string, id: string, archived: boolean): Note | null {
  const note = findNote(name, id)
  if (!note) return null
  note.archived = archived
  forgetDeleted(name)
  return note
}

/** Note id -> names it is shared with, as the owner typed them (unique ignoring case). */
const sharesByNote = new Map<string, string[]>()

/** Last name each user signed in with, shown as the owner of notes they share. */
const displayNames = new Map<string, string>()

export function sharedWith(id: string): string[] {
  return sharesByNote.get(id) ?? []
}

/** Gives `recipient` read access to one of `name`'s notes; sharing twice changes nothing. */
export function shareNote(name: string, id: string, recipient: string): boolean {
  if (!findNote(name, id)) return false
  const names = sharedWith(id)
  if (!names.some((other) => userKey(other) === userKey(recipient))) sharesByNote.set(id, [...names, recipient])
  return true
}

export function unshareNote(name: string, id: string, recipient: string): boolean {
  if (!findNote(name, id)) return false
  const names = sharedWith(id).filter((other) => userKey(other) !== userKey(recipient))
  if (names.length) sharesByNote.set(id, names)
  else sharesByNote.delete(id)
  return true
}

/** Notes others share with `name` that are still on their owner's list (not archived or deleted), with their current title. */
export function listSharedWith(name: string): SharedNote[] {
  const key = userKey(name)
  const shared: SharedNote[] = []
  for (const owner of notesByUser.keys()) {
    if (owner === key) continue
    for (const note of listNotes(owner)) {
      if (sharedWith(note.id).some((other) => userKey(other) === key)) {
        shared.push({ id: note.id, title: note.title, owner: displayNames.get(owner) ?? owner })
      }
    }
  }
  return shared
}

export function sameUser(a: string, b: string): boolean {
  return userKey(a) === userKey(b)
}

export function signIn(event: H3Event, name: string): void {
  displayNames.set(userKey(name), name)
  const id = randomUUID()
  sessions.set(id, name)
  setCookie(event, SESSION_COOKIE, id, { httpOnly: true, sameSite: 'lax', path: '/' })
}

export function signOut(event: H3Event): void {
  const id = getCookie(event, SESSION_COOKIE)
  const name = id ? sessions.get(id) : undefined
  if (name) forgetDeleted(name)
  if (id) {
    sessions.delete(id)
    flashBySession.delete(id)
  }
  deleteCookie(event, SESSION_COOKIE, { httpOnly: true, sameSite: 'lax', path: '/' })
}

export function currentUser(event: H3Event): string | null {
  const id = getCookie(event, SESSION_COOKIE)
  return id ? sessions.get(id) ?? null : null
}

/** Plain HTML form posts get redirects; JS (JSON) requests get status codes. */
export function isFormPost(event: H3Event): boolean {
  return (getRequestHeader(event, 'content-type') ?? '').includes('application/x-www-form-urlencoded')
}

/** Users the admin has made read-only, by user key; kept until made writable again or the account is deleted. */
const readOnlyUsers = new Set<string>()

export function isReadOnly(name: string): boolean {
  return readOnlyUsers.has(userKey(name))
}

/** Whether the user shows up on the admin page: has signed in or owns notes. */
export function userExists(name: string): boolean {
  const key = userKey(name)
  return displayNames.has(key) || notesByUser.has(key)
}

export function setReadOnly(name: string, readOnly: boolean): void {
  if (readOnly) readOnlyUsers.add(userKey(name))
  else readOnlyUsers.delete(userKey(name))
}

/**
 * Refuses a change to a read-only user's notes: form posts are sent to `page` with `error=read-only`, JSON requests get a 403.
 * Returns nothing when the user may change their notes.
 */
export function refuseReadOnly(event: H3Event, name: string, page: string) {
  if (!isReadOnly(name)) return undefined
  if (isFormPost(event)) return sendRedirect(event, `${page}${page.includes('?') ? '&' : '?'}error=read-only`, 303)
  throw createError({ statusCode: 403, statusMessage: READ_ONLY_ERROR, data: { code: 'read-only' } })
}

/** Every user who has signed in or owns notes, with their note count (archived included) and access, in name order. */
export function listUsers(): { name: string; notes: number; readOnly: boolean }[] {
  const keys = new Set([...displayNames.keys(), ...notesByUser.keys()])
  return [...keys]
    .sort()
    .map((key) => ({ name: displayNames.get(key) ?? key, notes: notesByUser.get(key)?.length ?? 0, readOnly: readOnlyUsers.has(key) }))
}

/** Removes every trace of the user: notes (archived included) and their shares, note numbering, undo, add limit, read-only access, display name and all sessions. Shares others made to the user stay with their owners. */
export function deleteAccount(name: string): void {
  const key = userKey(name)
  for (const note of notesByUser.get(key) ?? []) sharesByNote.delete(note.id)
  notesByUser.delete(key)
  lastNumberByUser.delete(key)
  lastDeletedByUser.delete(key)
  addTimesByUser.delete(key)
  readOnlyUsers.delete(key)
  displayNames.delete(key)
  for (const [id, other] of sessions) {
    if (userKey(other) !== key) continue
    sessions.delete(id)
    flashBySession.delete(id)
  }
}
export default defineEventHandler((event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const readOnly = refuseReadOnly(event, name, '/notes')
  if (readOnly) return readOnly
  const note = undoDelete(name)
  if (form) return sendRedirect(event, '/notes', 303)
  if (!note) throw createError({ statusCode: 404, statusMessage: 'Nothing to undo' })
  return note
})
/** `Delete selected` / `Archive selected`: acts on the checked notes; with none checked it does nothing. */
export default defineEventHandler(async (event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const readOnly = refuseReadOnly(event, name, '/notes')
  if (readOnly) return readOnly
  const body = await readBody<{ action?: unknown; ids?: unknown }>(event)
  const raw = body?.ids
  const ids = (Array.isArray(raw) ? raw : raw === undefined ? [] : [raw]).filter((id): id is string => typeof id === 'string')
  const action = body?.action
  if (action !== 'delete' && action !== 'archive') {
    if (form) return sendRedirect(event, '/notes', 303)
    throw createError({ statusCode: 400, statusMessage: 'Unknown action' })
  }
  const count = ids.length ? (action === 'delete' ? deleteNotes(name, ids) : archiveNotes(name, ids)) : 0
  if (form) return sendRedirect(event, '/notes', 303)
  return { action, count }
})
import { ARCHIVED_ERROR } from '#shared/types/note'

export default defineEventHandler((event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const readOnly = refuseReadOnly(event, name, '/notes')
  if (readOnly) return readOnly
  const id = getRouterParam(event, 'id') ?? ''
  if (findNote(name, id)?.archived) {
    if (form) return sendRedirect(event, '/archive', 303)
    throw createError({ statusCode: 409, statusMessage: ARCHIVED_ERROR, data: { code: 'archived' } })
  }
  const removed = deleteNote(name, id)
  if (form) return sendRedirect(event, '/notes', 303)
  if (!removed) throw createError({ statusCode: 404, statusMessage: 'Note not found' })
  return { removed }
