export interface Note {
  id: string
  title: string
  /** Free text, empty until the user writes one on the note's page; line breaks are kept. */
  body: string
  /** Identifies the note among its owner's notes: 1, 2, ... in order of adding; never reused. */
  number: number
  pinned: boolean
  /** Archived notes are read-only and leave the list page until restored. */
  archived: boolean
  /** ISO 8601 UTC timestamp, set by the server when the note is created. */
  createdAt: string
  /** Names the note is shared with; only sent to its owner. */
  sharedWith?: string[]
}

/** A note another user shares: only what the recipient may see. */
export interface SharedNote {
  id: string
  title: string
  owner: string
}

export interface NotesResponse {
  name: string | null
  notes: Note[]
  /** Title of the most recent delete that can still be undone (list page only). */
  deletedTitle?: string | null
  /** Notes other users share with this user (list page only). */
  shared?: SharedNote[]
  /** The admin has made this account read-only: it may read but not change its notes. */
  readOnly?: boolean
}

/** The `Shared with me` part of the list page on its own, polled while the page is open. */
export interface SharedNotesResponse {
  name: string | null
  shared: SharedNote[]
}

/** One note page: the signed-in user's note with that number, or `null` when they have none. */
export interface NoteResponse {
  name: string | null
  note: Note | null
  /** Outcome of a save posted without JavaScript, shown once on the page it redirected to. */
  flash?: NoteFlash | null
}

/** Codes of what is wrong with a save, one per field. */
export interface NoteSaveErrors {
  title?: 'empty' | 'too-long' | 'duplicate'
  body?: 'too-long'
}

/** Either `saved`, or the fields exactly as typed together with their errors. */
export interface NoteFlash {
  saved?: boolean
  title?: string
  body?: string
  errors?: NoteSaveErrors
}

export const RATE_LIMIT_ERROR = 'Too many notes, try again in a minute'

export const ARCHIVED_ERROR = 'Archived notes are read-only'

export const READ_ONLY_ERROR = 'Your account is read-only'

export const SHARE_SELF_ERROR = 'You cannot share with yourself'
export const SHARE_NAME_ERROR = 'Name must be 2-20 letters'

export const NAME_PATTERN = /^[A-Za-z]{2,20}$/
export const NOTE_MAX_LENGTH = 60
export const BODY_MAX_LENGTH = 1000

export const SAVE_MESSAGES = {
  title: {
    empty: 'Write a title first',
    'too-long': `Use at most ${NOTE_MAX_LENGTH} characters`,
    duplicate: 'You already have a note with this title',
  },
  body: {
    'too-long': `Use at most ${BODY_MAX_LENGTH} characters in the body`,
  },
} as const

/** Names are case-insensitive, so `Admin` is the same user as `admin`. */
export function isAdmin(name: string | null | undefined): boolean {
  return name?.toLowerCase() === 'admin'
}

/** One row of the admin page: a user and how many notes they own, archived ones included. */
export interface AdminUser {
  name: string
  notes: number
  /** Read-only accounts may read but not change their notes. */
  readOnly: boolean
}

export interface AdminResponse {
  name: string | null
  /** Only filled in for the admin. */
  allowed: boolean
  users: AdminUser[]
}
import type { NotesResponse } from '#shared/types/note'

export default defineEventHandler((event): NotesResponse => {
  const name = currentUser(event)
  if (!name) return { name, notes: [], deletedTitle: null }
  return {
    name,
    notes: listNotes(name).map((note) => ({ ...note, sharedWith: sharedWith(note.id) })),
    deletedTitle: lastDeleted(name)?.title ?? null,
    shared: listSharedWith(name),
    readOnly: isReadOnly(name),
  }
})

